// Embed only reviewed local PNGs; no runtime package or image requests.
import { readFileSync, writeFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
const root = new URL('./', import.meta.url);
const manifest = JSON.parse(readFileSync(new URL('provenance.json', root), 'utf8'));
for (const item of manifest.fugueFiles) {
  if (createHash('sha256').update(readFileSync(new URL(item.file, root))).digest('hex') !== item.sha256) throw new Error(`Source changed: ${item.file}`);
}
const images = {};
for (const file of new Set(Object.values(manifest.glyphs))) {
  const bytes = readFileSync(new URL(file, root));
  if (!bytes.subarray(0, 8).equals(Buffer.from([137, 80, 78, 71, 13, 10, 26, 10])) || bytes.readUInt32BE(16) !== 16 || bytes.readUInt32BE(20) !== 16) throw new Error(`Not a 16px PNG: ${file}`);
  images[file] = `data:image/png;base64,${bytes.toString('base64')}`;
}
const output = `// Generated by vendor/paint-icons/generate.mjs. Fugue CC BY 3.0 + derived Tabler MIT.\n// See vendor/paint-icons/README.md and public/THIRD_PARTY_NOTICES.txt.\nconst images: Readonly<Record<string, string>> = Object.freeze(${JSON.stringify(images, null, 2)});\nconst glyphs: Readonly<Record<string, string>> = Object.freeze(${JSON.stringify(manifest.glyphs, null, 2)});\nexport const paintBitmaps: Readonly<Record<string, string>> = Object.freeze(Object.fromEntries(Object.entries(glyphs).map(([name, file]) => [name, images[file]!])));\n`;
const target = new URL('../../src/shared/paint-bitmaps.ts', root);
if (process.argv.includes('--check')) {
  if (readFileSync(target, 'utf8') !== output) throw new Error('Paint bitmap catalog is stale.');
} else writeFileSync(target, output);
console.log(`${manifest.fugueFiles.length} Fugue hashes, ${Object.keys(images).length} native bitmaps and ${Object.keys(manifest.glyphs).length} mappings verified.`);
